import { View, Text, Pressable, FlatList, StyleSheet } from "react-native";
import { useReducer } from "react";
import { registerRootComponent } from "expo";

function reducer(state, action) {
  if (action.type === "add") return [...state, action.name];
  // энд бичнэ үү: "clear" action — сагсыг хоослоно
  return state;
}

function App() {
  const [items, dispatch] = useReducer(reducer, ["Чихэвч", "Цүнх"]);
  return (
    <View style={styles.s}>
      <Text nativeID="count" style={styles.h}>Сагс ({items.length})</Text>
      <Pressable nativeID="add" style={styles.b} onPress={() => dispatch({ type: "add", name: "Ном" })}><Text style={styles.t}>Ном нэмэх</Text></Pressable>
      <Pressable nativeID="clear" style={styles.b2} onPress={() => dispatch({ type: "clear" })}><Text style={styles.t}>Цэвэрлэх</Text></Pressable>
      <FlatList data={items} keyExtractor={(x, i) => String(i)} renderItem={({ item }) => <Text testID="row" style={styles.row}>{item}</Text>} />
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, gap: 10, padding: 20 },
  h: { fontSize: 22, fontWeight: "bold" },
  b: { backgroundColor: "#2563eb", padding: 12, borderRadius: 10, alignItems: "center" },
  b2: { backgroundColor: "#dc2626", padding: 12, borderRadius: 10, alignItems: "center" },
  t: { color: "#fff", fontWeight: "bold" }, row: { padding: 12, backgroundColor: "#f1f5f9", borderRadius: 8 },
});

registerRootComponent(App);

import { View, Text, Pressable, FlatList, StyleSheet } from "react-native";
import { useReducer } from "react";
import { registerRootComponent } from "expo";

function reducer(state, action) {
  if (action.type === "add") return [...state, action.name];
  if (action.type === "clear") return [];
  return state;
}

function App() {
  const [items, dispatch] = useReducer(reducer, ["Чихэвч", "Цүнх"]);
  return (
    <View style={styles.s}>
      <Text nativeID="count" style={styles.h}>Сагс ({items.length})</Text>
      <Pressable nativeID="add" style={styles.b} onPress={() => dispatch({ type: "add", name: "Ном" })}><Text style={styles.t}>Ном нэмэх</Text></Pressable>
      <Pressable nativeID="clear" style={styles.b2} onPress={() => dispatch({ type: "clear" })}><Text style={styles.t}>Цэвэрлэх</Text></Pressable>
      <FlatList data={items} keyExtractor={(x, i) => String(i)} renderItem={({ item }) => <Text testID="row" style={styles.row}>{item}</Text>} />
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, gap: 10, padding: 20 },
  h: { fontSize: 22, fontWeight: "bold" },
  b: { backgroundColor: "#2563eb", padding: 12, borderRadius: 10, alignItems: "center" },
  b2: { backgroundColor: "#dc2626", padding: 12, borderRadius: 10, alignItems: "center" },
  t: { color: "#fff", fontWeight: "bold" }, row: { padding: 12, backgroundColor: "#f1f5f9", borderRadius: 8 },
});

registerRootComponent(App);
